{
  "items": [
    {
      "stem": "3 + 5 =",
      "answer": "8",
      "solution": "将3和5合并，从3开始往后数5个数：4、5、6、7、8，所以3加5等于8。"
    },
    {
      "stem": "9 - 4 =",
      "answer": "5",
      "solution": "从9里面去掉4，可以想9分成4和5，所以9减4等于5。"
    },
    {
      "stem": "6 + 0 =",
      "answer": "6",
      "solution": "任何数加上0都等于它本身，所以6加0等于6。"
    },
    {
      "stem": "10 - 2 =",
      "answer": "8",
      "solution": "10可以分成2和8，去掉2还剩8，所以10减2等于8。"
    },
    {
      "stem": "7 + 7 =",
      "answer": "14",
      "solution": "这是进位加法的基础，7加7等于14，也可以想7加3得10，再加4得14。"
    },
    {
      "stem": "15 - 5 =",
      "answer": "10",
      "solution": "15是由1个十和5个一组成的，减去5个一，还剩1个十，即10。"
    },
    {
      "stem": "4 + 8 =",
      "answer": "12",
      "solution": "使用凑十法，把4分成2和2，8加2得10，10再加2得12。"
    },
    {
      "stem": "12 - 3 =",
      "answer": "9",
      "solution": "可以使用破十法，12分成10和2，10减3得7，7加2得9；或者想3加9等于12，所以12减3等于9。"
    },
    {
      "stem": "5 + 6 =",
      "answer": "11",
      "solution": "5加5等于10，再加1等于11，所以5加6等于11。"
    },
    {
      "stem": "18 - 8 =",
      "answer": "10",
      "solution": "18是由1个十和8个一组成的，减去8个一，还剩1个十，即10。"
    }
  ]
}
